    "\nCREATE TABLE media_sources (\n\tid VARCHAR(36) NOT NULL CONSTRAINT ck_media_sources_uuid_length CHECK (length(id) = 36), \n\tagent_id VARCHAR(36) NOT NULL, \n\tcreated_at VARCHAR(40) NOT NULL, \n\tkind VARCHAR(20) NOT NULL, \n\tbvid VARCHAR(12) NOT NULL, \n\taid VARCHAR(19) NOT NULL, \n\tcid VARCHAR(19) NOT NULL, \n\ttitle VARCHAR(300) NOT NULL, \n\tduration_s INTEGER NOT NULL, \n\tconfig_id VARCHAR(36) NOT NULL, \n\tconfig_revision_id VARCHAR(36) NOT NULL, \n\tCONSTRAINT pk_media_sources PRIMARY KEY (id), \n\tCONSTRAINT fk_media_sources_config_id_configurations FOREIGN KEY(config_id, agent_id) REFERENCES configurations (id, agent_id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_media_sources_config_revision_id_configuration_revisions FOREIGN KEY(config_revision_id, agent_id) REFERENCES configuration_revisions (id, agent_id) ON DELETE RESTRICT, \n\tCONSTRAINT uq_media_sources_agent_id UNIQUE (agent_id, bvid), \n\tCONSTRAINT ck_media_sources_source CHECK (kind='bilibili_video' AND length(bvid)=12 AND substr(bvid,1,2)='BV' AND substr(bvid,3) NOT GLOB '*[^0-9A-Za-z]*' AND length(aid) BETWEEN 1 AND 19 AND length(cid) BETWEEN 1 AND 19 AND typeof(duration_s)='integer' AND duration_s BETWEEN 1 AND 7200 AND length(title)<=300), \n\tCONSTRAINT uq_media_sources_id UNIQUE (id, agent_id), \n\tCONSTRAINT fk_media_sources_agent_id_agents FOREIGN KEY(agent_id) REFERENCES agents (id) ON DELETE RESTRICT\n)\n\n",
